# Lower gently, release, and return the right arm home to reveal the settled placement.
obs, used, reason = move_ee_slow({'right':[-0.073,-0.1744,0.928]+down_yaw(213)}, {'left':0.0,'right':0.0}, 20, linear_step=0.004, settle_steps=2, min_opening={'left':0.06,'right':0.06})
print('lower',used,reason)
if reason == 'reached':
    obs, used, reason = move_ee({}, {'left':0.0,'right':1.0}, 6, settle_steps=5)
    print('release',used,reason)
    if reason == 'reached':
        obs, used, reason = move_ee({'right':[-0.073,-0.1744,1.05]+down_yaw(213)}, {'left':0.0,'right':1.0}, 8, settle_steps=2)
        print('retract',used,reason)
        if reason == 'reached':
            left_hold = list(obs['state']['left_arm_joint_state'])
