                obs, reward, terminated, truncated, info = step({'left_arm_joint_state':left_hold,'right_arm_joint_state':origin['right_arm_joint_state'],'left_ee_joint_state':[0.0],'right_ee_joint_state':[1.0]})
                if terminated or truncated:
                    break
